      // قائمة حسابات ومتابعة قادة الفوج مع تهيئة الحسابات المعتمدة
      // قائمة حسابات ومتابعة قادة الفوج مع تهيئة الحسابات المعتمدة
      const [leadersTracking, setLeadersTracking] = useState(() => {
        const isDemo = (groupCode === "الفوج-الكشفي-01");
        const saved = localStorage.getItem(`scout_leaders_${groupCode}`);
        if (saved !== null) {
          try {
            const list = JSON.parse(saved);
            if (Array.isArray(list)) return list;
          } catch (e) {}
        }
        return isDemo ? defaultLeadersList : [];
      });

      // حسابات المشرفين (نظام ديناميكي متعدد الحسابات بدون حصر متجاوب مع أي عدد)
      const [supervisorAccounts, setSupervisorAccounts] = useState(() => {
        const isDemo = (groupCode === "الفوج-الكشفي-01");
        const saved = localStorage.getItem(`scout_supervisors_${groupCode}`);
        if (saved !== null) {
          try {
            const list = JSON.parse(saved);
            if (Array.isArray(list)) return list;
          } catch (e) {}
        }
        return isDemo ? defaultSupervisorsList : [];
      });

      const [showSupervisorAccountsModal, setShowSupervisorAccountsModal] = useState(false);
      const [editingSupervisorModal, setEditingSupervisorModal] = useState(null); // { mode: "add" | "edit", account?: {...} }
      const [supervisorSearchTerm, setSupervisorSearchTerm] = useState("");
      const [showSupPasswords, setShowSupPasswords] = useState(false);

      // نظام الإشعارات للمشرف عند تحديثات القادة
      const [notifications, setNotifications] = useState(() => {
        const saved = localStorage.getItem(`scout_notifications_${groupCode}`);
        return saved ? JSON.parse(saved) : [];
      });

      // سجل وإحصائيات الشارات المتحصل عليها من طرف الفتية
      const [badgeAwards, setBadgeAwards] = useState(() => {
        const saved = localStorage.getItem(`scout_badge_awards_${groupCode}`);
        return saved ? JSON.parse(saved) : [];
      });
      const [showAddBadgeModal, setShowAddBadgeModal] = useState(false);
      const [badgeSearchQuery, setBadgeSearchQuery] = useState("");
      const [badgeSelectedScoutId, setBadgeSelectedScoutId] = useState(null);

      // دالة توحيد ومطابقة المراتب والشارات الكشفية (مبتدئ، ثان، أول)
      const normalizeStage = (st) => {
        if (!st) return "مبتدئ";
        const s = String(st).trim().toLowerCase();
        // الجوالة: الإعداد، التدريب، الخدمة
        if (s.includes("إعداد") || s.includes("اعداد")) return "الإعداد";
        if (s.includes("تدريب")) return "التدريب";
        if (s.includes("خدمة") || s.includes("انطلاق")) return "الخدمة";
        
        // بقية الأصناف: مبتدئ، ثانٍ، أول
        if (s.includes("مبتدئ") || s.includes("مبتدىء") || s.includes("مبتدء") || s.includes("مبتدئة")) return "مبتدئ";
        if (s.includes("ثان") || s.includes("ثاني") || s.includes("ثانية") || s.includes("ثانٍ")) return "ثاني";
        if (s.includes("أول") || s.includes("اول") || s.includes("أولى") || s.includes("اولى")) return "أول";
        return s;
      };

      // دالة استخراج وتنسيق اسم المرتبة حسب صنف الفتى
      const getStageDisplayName = (stage, branch = null) => {
        const norm = normalizeStage(stage);
        if (branch === "جوالة" || norm === "الإعداد" || norm === "التدريب" || norm === "الخدمة") {
          if (norm === "مبتدئ" || norm === "الإعداد") return "الإعداد";
          if (norm === "ثاني" || norm === "التدريب") return "التدريب";
          if (norm === "أول" || norm === "الخدمة") return "الخدمة";
        }
        if (norm === "ثاني") return "ثانٍ";
        return norm;
      };

      // دالة استخراج مرتبة المحور أو العنصر بالمنهاج
      const getCategoryStage = (cat) => {
        if (cat && cat.stage) return normalizeStage(cat.stage);
        if (cat && cat.title) {
          const t = cat.title;
          if (t.includes("مبتدئ") || t.includes("مبتدىء")) return "مبتدئ";
          if (t.includes("ثان") || t.includes("ثاني")) return "ثاني";
          if (t.includes("أول") || t.includes("اول")) return "أول";
        }
        return "مبتدئ";
      };

      const getItemStage = (item, cat) => {
        if (item && item.stage) return normalizeStage(item.stage);
        return getCategoryStage(cat);
      };

      // فحص ومنح الشارة تلقائياً عند إتمام متطلبات المرحلة والترقية للمرحلة الموالية
      const checkAndAwardStage = (sc, updatedReqs) => {
        if (!sc) return null;
        const curStage = normalizeStage(sc.stage);
        const curCats = curriculumRef.current || [];
        const stageReqIds = [];
        curCats.forEach(cat => {
          const catStage = getCategoryStage(cat);
          (cat.items || []).forEach(item => {
            const itemStage = item.stage ? normalizeStage(item.stage) : catStage;
            if (itemStage === curStage) {
              stageReqIds.push(item.id);
            }
          });
        });

        if (stageReqIds.length > 0 && stageReqIds.every(id => (updatedReqs || []).includes(id))) {
          let badgeName = "شارة مبتدئ";
          let nextStage = "ثاني";
          if (curStage === "مبتدئ") {
            badgeName = "شارة مبتدئ";
            nextStage = "ثاني";
          } else if (curStage === "ثاني") {
            badgeName = "شارة كشاف ثانٍ";
            nextStage = "أول";
          } else if (curStage === "أول") {
            badgeName = "شارة كشاف أول";
            nextStage = "أول (مكتمل)";
          }

          const alreadyHas = (badgeAwardsRef.current || []).some(
            b => b.scoutId === sc.id && (b.badgeName === badgeName || (b.badgeName && b.badgeName.includes(curStage)))
          );

          const autoBadge = {
            id: "badge-auto-" + Date.now() + "-" + Math.random().toString(36).substr(2, 4),
            scoutId: sc.id,
            scoutName: sc.name,
            unit: sc.unit,
            awardType: "شارة",
            badgeName: badgeName,
            dateAwarded: new Date().toISOString().split('T')[0],
            issuedBy: "اعتماد المنهاج الكشفي تلقائياً (إتمام المتطلبات)",
            notes: `تم منح الشارة تلقائياً لاستيفاء واجتياز جميع متطلبات مرتبة (${curStage}) بنجاح.`,
            createdAt: new Date().toISOString(),
            updatedAt: new Date().toISOString()
          };

          return {
            autoBadge: alreadyHas ? null : autoBadge,
            nextStage,
            badgeName,
            curStage,
            scoutName: sc.name
          };
        }
        return null;
      };
